/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  TopModule dut(.clk(clk),.rst(rst),.data(data),.flag(flag));
  always #5 clk=~clk;
  task step(input bit d);
    begin
      data=d;
      @(posedge clk);
      #1;
      "'$display("t=%0t data=%0b state=%0d nstate=%0d flag=%0b", $time, data, dut.state, dut.nstate, flag);
    end
  endtask
  initial begin
    #1; rst=0; data=0;
    @(posedge clk); #1; $display("reset state=%0d flag=%0b", dut.state, flag);
    rst=1;
    step(1); step(0); step(1); step(1); // 1011
    step(0); step(1); step(1); step(1); // continue to 10110111
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

