/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
-                S3     : nstate <= data? S4: S0;
+                S3     : nstate <= data? S4: S2;
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  TopModule dut(.clk(clk),.rst(rst),.data(data),.flag(flag));
  always #5 clk=~clk;

  task step(input bit d);
    begin
      data=d;
      @(posedge clk);
      #1;
      "'$display("t=%0t data=%0b state=%0d flag=%0b", $time, data, dut.state, flag);
    end
  endtask

  initial begin
    @(posedge clk); rst=1; #1;
    // baseline detection: 1011 -> one pulse on next cycle
    step(1); step(0); step(1); step(1); step(0);
    // critical overlap case: 101011 contains 1011 starting at bit 3
    rst=0; @(posedge clk); rst=1; #1;
    step(1); step(0); step(1); step(0); step(1); step(1); step(0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

