 1	module TopModule(
 2		input wire clk  ,
 3		input wire rst  ,
 4		input wire data ,
 5		output reg flag
 6	);
 7	//*************code***********//
 8	    parameter S0=0, S1=1, S2=2, S3=3, S4=4;
 9	    reg [2:0] state, nstate;
10	    
11	    always@(posedge clk or negedge rst) begin
12	        if(~rst)
13	            state <= S0;
14	        else
15	            state <= nstate;
16	    end
17	    
18	    always@(*) begin
19	        if(~rst)
20	            nstate <= S0;
21	        else
22	            case(state)
23	                S0     : nstate <= data? S1: S0;
24	                S1     : nstate <= data? S1: S2;
25	                S2     : nstate <= data? S3: S0;
26	                S3     : nstate <= data? S4: S2;
27	                S4     : nstate <= data? S1: S2;
28	                default: nstate <= S0;
29	            endcase
30	    end
31	    
32	    always@(posedge clk or negedge rst) begin
33	        if(~rst)
34	            flag <= 0;
35	        else
36	            flag <= state==S4;
37	    end
38	
39	//*************code***********//
40	endmodule
